fun main() {
    // tokenizer with alternation of named groups
    val tok = Regex("(?<num>\\d+(?:\\.\\d+)?)|(?<id>[A-Za-z_]\\w*)|(?<op>[-+*/()=])|(?<ws>\\s+)")
    for (m in tok.findAll("x1 = 3.14 * (y + 42)")) {
        val kind = listOf("num", "id", "op", "ws").first { m.groups[it] != null }
        if (kind != "ws") println(kind + ":" + m.value + "@" + m.range)
    }
    // log line parsing
    val log = Regex("^(?<ip>\\d{1,3}(?:\\.\\d{1,3}){3}) - - \\[(?<ts>[^\\]]+)\\] \"(?<method>GET|POST) (?<path>\\S+) HTTP/(?<ver>[\\d.]+)\" (?<status>\\d{3})$")
    val lm = log.matchEntire("192.168.0.1 - - [10/Oct/2023:13:55:36] \"GET /index.html HTTP/1.1\" 200")!!
    println(lm.groups["ip"]!!.value + " " + lm.groups["method"]!!.value + " " + lm.groups["path"]!!.value + " " + lm.groups["status"]!!.value)
    println(lm.groupValues.size)
    println(lm.groups["ts"]!!.range)
    // csv-ish split with lookahead
    println("a,b,\"c,d\",e".split(Regex(",(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)")))
    // camelCase split
    println("camelCaseStringHTTPServer".split(Regex("(?<=[a-z])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])")))
    println("snake_case_here".replace(Regex("_([a-z])")) { it.groupValues[1].uppercase() })
    println("CamelCaseHere".replace(Regex("([a-z])([A-Z])"), "$1_$2").lowercase())
    println("  trim   inner   spaces  ".trim().replace(Regex("\\s+"), " "))
    // replace with lambda using groups and ranges
    println(Regex("(?<k>\\w+)=(?<v>\\w+)").replace("a=1, b=2") { "${it.groups["v"]!!.value}=${it.groups["k"]!!.value}" })
    println(Regex("\\d+").replace("a1b22") { it.range.first.toString() })
    println(Regex("a").replace("banana") { m -> if (m.range.first > 2) "A" else "a" })
    println(Regex("[$]\\{(\\w+)}").replace("hi \${name}, \${x}") { "<" + it.groupValues[1] + ">" })
    println(Regex("x").replace("axb") { "\$1\\" })
    println(Regex("(?<n>b)").replace("abc", "[\${n}]"))
    try {
        Regex("(a)").replace("a", "\$2")
    } catch (e: IndexOutOfBoundsException) {
        println("ioobe")
    }
    try {
        Regex("(a)").replace("a", "\${zz}")
    } catch (e: IllegalArgumentException) {
        println("iae")
    }
    // MatchResult API
    val m = Regex("(\\d+)-(\\d+)?").find("10- 20-30")!!
    println(m.groups.size)
    println(m.groups[2])
    println(m.groups[1]!!.range)
    println(m.groupValues)
    println(m.destructured.component1())
    println(m.destructured.toList())
    println(m.groups.filterNotNull().map { it.value })
    println(m.groups.indices)
    println(m.range.last)
    println(m.next()!!.groupValues)
    println(m.next()!!.next())
    // findAll with start index and sequences
    println(Regex("\\w+").findAll("one two three", 4).map { it.value }.toList())
    println(Regex("\\w+").findAll("one two three").first().value)
    println(Regex("\\w+").findAll("one two three").last().value)
    println(Regex("\\w+").findAll("one two three").toList().size)
    println(Regex("\\w+").findAll("one two three").map { it.value.length }.sum())
    println(Regex("\\w+").findAll("").toList())
    println(Regex("(?<l>[a-z])(?<d>\\d)").findAll("a1b2c3").map { it.groups["l"]!!.value + it.groups["d"]!!.value }.toList())
    println(Regex("[a-z]+").findAll("ab cd").iterator().next().value)
    // split edge cases
    println("a--b".split(Regex("-")))
    println("a--b".split(Regex("-+")))
    println("abc".split(Regex("")))
    println("abc".split(Regex(""), 2))
    println("".split(Regex(",")))
    println(",".split(Regex(",")))
    println("a,b".split(Regex(","), 1))
    println("2024-01-02T03:04".split(Regex("[-T:]")))
    println("a1b22c".split(Regex("\\d+"), 2))
    println("one  two".split(Regex("\\s")).size)
    println("x".split(Regex("x")))
    println("xx".split(Regex("x")))
    println("axb".split(Regex("(?<=a)|(?=b)")))
    // more syntax
    println(Regex("\\R").split("a\r\nb\nc\rd").size)
    println(Regex("\\h+").find("a \t b")!!.value.length)
    println(Regex("[\\s&&[^\\n]]+").find("a \n b ")!!.range)
    println(Regex("\\p{IsAlphabetic}+").find("12ab")!!.value)
    println(Regex("\\p{javaLowerCase}+").find("ABcd")!!.value)
    println(Regex("\\p{Digit}+\\p{Space}\\p{Alnum}").find("12 a")!!.value)
    println(Regex("\\P{Digit}+").find("ab12")!!.value)
    println(Regex("[\\p{L}&&[^a-c]]+").find("abcdef")!!.value)
    println(Regex("(?x) a b  c # comment").matches("abc"))
    println(Regex("a{2,}").find("aaaa")!!.value)
    println(Regex("a{2,3}?").find("aaaa")!!.value)
    println(Regex("(?:a|b)*c").find("ababc")!!.value)
    println(Regex("(a*)*b").matches("aaab"))
    println(Regex("(a|b)*?c").find("abc")!!.value)
    println(Regex("^$").matches(""))
    println(Regex("^$").find("")!!.range)
    println(Regex("$").find("abc")!!.range)
    println(Regex("^").findAll("a\nb").count())
    println(Regex("(?m)^").findAll("a\nb").count())
    println(Regex("(?m)$").findAll("a\nb").count())
    println(Regex("a$").find("a\n")!!.range)
    println(Regex(".").findAll("a\nb").count())
    println(Regex("(?s).").findAll("a\nb").count())
    println(Regex("(?i)straße").matches("STRASSE"))
    println(Regex("é", RegexOption.IGNORE_CASE).matches("É"))
    println(Regex("[a-z]+", RegexOption.IGNORE_CASE).matches("AbC"))
    println(Regex("\\u00e9").matches("é"))
    println(Regex("\\d+(?=%)").find("50% of 20")!!.value)
    println(Regex("(?<=\\d{2})x").find("1x12x")!!.range)
    println(Regex("(?<!a)b").findAll("ab cb b").map { it.range.first }.toList())
    println(Regex("(?=(\\w\\w))").findAll("abcd").map { it.groupValues[1] }.toList())
    println(Regex("^(?:(?!ab).)*$").matches("xxaxbx"))
    println(Regex("^(?:(?!ab).)*$").matches("xxabx"))
    println(Regex("\\b(\\w+)\\s+\\1\\b").find("this is is a test")!!.value)
    println(Regex("(?<a>.)(?<b>.)\\k<b>\\k<a>").matches("abba"))
    println(Regex("(a)?b\\1").matches("b"))
    println(Regex("[]a]+").find("]a]")?.value)
    println(Regex("[a\\]]+").find("a]")?.value)
    println(Regex("[\\[\\]]+").find("x[]")?.value)
    println(Regex("[-a]+").find("-a-")?.value)
    println(Regex("[a-]+").find("-a-")?.value)
    println(Regex("[^]]+").find("ab]")?.value)
    println(Regex("\\.").find("a.b")!!.range)
    println(Regex("a|").find("b")!!.range)
    println(Regex("a||b").findAll("ab").count())
    println(Regex("()").find("a")!!.groupValues)
    println(Regex("(?:)").find("a")!!.range)
    // convenience extensions
    println("The Quick".contains(Regex("quick", RegexOption.IGNORE_CASE)))
    println("a1b2".replace(Regex("\\d")) { (it.value.toInt() + 1).toString() })
    println("abc".matches(Regex("[a-c]+")))
    println("aXb".replaceFirst(Regex("[A-Z]"), "-"))
    println("a b c".replaceFirst(Regex(" "), "_"))
    println(Regex("[a-c]").findAll("abcabc").map { it.value }.joinToString(""))
    println(Regex("ab").toString())
    println(Regex("ab", RegexOption.IGNORE_CASE).options)
    println(Regex("ab") == Regex("ab"))
    println("hello world".split(Regex("o")).map { it.length })
    println("hello".toRegex().matches("hello"))
    println("x".toRegex().find("axb")?.range)
    println(Regex("[0-9a-f]{2}").findAll("1f 2G a0").map { it.value }.toList())
    println(Regex("\\d{3}-\\d{4}").containsMatchIn("call 555-1234 now"))
    println(Regex("^[\\w.+-]+@\\w+\\.\\w{2,}$").matches("john.doe+tag@example.com"))
    println(Regex("^\\d{4}-\\d{2}-\\d{2}$").matches("2024-02-30"))
    println(Regex("^(?:25[0-5]|2[0-4]\\d|1?\\d?\\d)(?:\\.(?:25[0-5]|2[0-4]\\d|1?\\d?\\d)){3}$").matches("255.1.20.199"))
    println(Regex("#([0-9a-fA-F]{2})([0-9a-fA-F]{2})([0-9a-fA-F]{2})").find("color: #FFa500;")!!.destructured.toList().map { it.toInt(16) })
}
